void settle(String batchId) {
    Optional<RedisLock.Lease> lease = lock.tryAcquire("settle", Duration.ofSeconds(30));
    if (lease.isEmpty()) return;                                   // another pod is running the batch
    try {
        String file = buildPayoutFile(batchId);
        boolean written = ledger.write(batchId, lease.get().fence(), file);   // the store checks the fence
        if (!written) log.warn("lost the lock to a newer holder; file not written");
    } finally {
        lock.release(lease.get());                                 // compare-and-delete: never another pod's lock
    }
}

