inline fun <T> RedisLock.withLock(resource: String, lease: Duration, block: (RedisLock.Lease) -> T): T? {
    val held = tryAcquire(resource, lease).orElse(null) ?: return null   // another pod is running it
    try {
        return block(held)
    } finally {
        release(held)                                              // compare-and-delete: never another pod's lock
    }
}

fun settle(batchId: String) {
    lock.withLock("settle", Duration.ofSeconds(30)) { lease ->
        val written = ledger.write(batchId, lease.fence(), buildPayoutFile(batchId))   // the store checks the fence
        if (!written) log.warn("lost the lock to a newer holder; file not written")
    }
}

