static final String RELEASE = """
        if redis.call('GET', KEYS[1]) == ARGV[1] then
            return redis.call('DEL', KEYS[1])
        end
        return 0
        """;

boolean release(String key, String token) {
    return Long.valueOf(1).equals(redis.eval(RELEASE, List.of(key), List.of(token)));   // compare and delete, one command
}

boolean releaseOnRedis84(String key, String token) {
    return redis.delex(key, CompareCondition.valueEq(token)) == 1;                      // DELEX key IFEQ token
}
